mapper.select:
SELECT COUNT(*)
FROM quant_trade_cycle c
WHERE c.credential_id IN
#{id}
AND c.symbol=#{symbol}
AND c.opened_at>=#{from}
AND c.opened_at<#{to}

SELECT COUNT(*)
FROM quant_trade_cycle_scope s
WHERE s.credential_id IN
#{id}
AND (s.projection_status<>'READY' OR s.incomplete_count>0)
AND s.symbol=#{symbol}

SELECT COUNT(*)
FROM quant_trade_cycle c
WHERE c.credential_id IN
#{id}
AND c.reconstruction_source='INFERRED'
AND c.symbol=#{symbol}
AND c.opened_at>=#{from}
AND c.opened_at<#{to}
